window.__reformedWorks["schaff_creeds3_05"] = {"id":"schaff_creeds3_05","a":"Schaff, Philip","t":"The Ten Theses of Berne, A.D. 1528","u":"https://ccel.org/ccel/schaff/creeds3","c":[{"t":"The Ten Theses of Berne, A.D. 1528","s":[{"t":"","p":["These Ten Conclusions were carefully prepared by Berthold Haller and Francis Kolb, Reformed ministers at Berne, and, at their request, revised and published by Zwingli (in German, Latin, and French) for a large religious Conference held in the capital of Switzerland, Jan. 7–26, 1528. They were approved by all the leading Swiss Reformers, and also by Ambrosius Blaarer of Constance, Bucer and Capito of Strasburg, and others, who attended the Conference. The result of the Conference was the complete triumph of the Reformation in Berne. They are a model of brevity. Niemeyer gives the German original in the Swiss dialect from the Zurich edition of 1528. An English version is given in Vol. I. p.365.","Alles Gott und seinem heiligen Worte zur Ehre!"]}]}]};
